pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address immutable deployer = address(this);

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address adr, bytes calldata data, uint256 value) public {
        // Bound value to something reasonable so we can deal it
        vm.assume(value <= address(this).balance);
        // Ensure sender is not the Owner (deployer) to test the property
        address actor = address(uint160(uint256(keccak256(abi.encode(adr, data, value)))));
        vm.assume(actor != deployer);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // Fund actor
        vm.deal(actor, value);

        // Before state: deployer is Owner
        address expectedOwner = c.Owner();

        vm.prank(actor);
        (bool success, ) = address(c).call{value: value}(
            abi.encodeWithSignature("Command(address,bytes)", adr, data)
        );
        // If the call reverts, we catch it; property holds either way

        // After any call to Command (whether it reverts or succeeds), the Owner must remain the deployer.
        // The reference enforces this because only the Owner can call Command; the bug removes that check,
        // allowing a non-Owner to potentially change Owner if adr == address(c) and data targets a function that changes Owner.
        assertTrue(c.Owner() == expectedOwner);
    }
}

