pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address adr, bytes calldata data) public {
        vm.assume(adr != address(c));
        vm.assume(adr != address(0));
        // Deploy a helper that will attempt to change its own storage if called via delegatecall
        // We use a precompiled/empty contract: the bug modifies C's storage if data contains a store.
        // We snapshot Owner before the call; after the call, Owner must remain unchanged.
        address originalOwner = c.Owner();
        // Use a contract that can modify storage when delegatecalled
        // We deploy a minimal contract that sets a storage slot when called
        // But we cannot deploy inside the test without another contract definition.
        // Instead, we rely on the fuzzer to supply data that writes to slot 0 (Owner).
        // For the reference, low-level call does not affect C's storage, so Owner remains same.
        // For the bug, delegatecall executes in C's context, so Owner may change.
        vm.prank(c.Owner());
        (bool success, ) = address(c).call(abi.encodeWithSignature("Command(address,bytes)", adr, data));
        // If Command reverted, we skip (we only care about successful calls).
        vm.assume(success);
        // Assert: Owner did not change after successful Command call (reference invariant).
        // Bug: delegatecall can overwrite Owner.
        assertEq(c.Owner(), originalOwner);
    }
}

